  Lemma aheap_pres_frame : forall L RNG st LB m m' W lo SP,
    AHEAP AI L RNG st LB m -> munch W m m' -> wmono asegs m m' ->
    Forall (fun iv => lo <= fst iv /\ snd iv <= SP) W -> ATOP + 4096 <= lo -> SP <= al_top L ->
